function s(v){return String(v==null?'':v).trim();}
function nz(x){return s(x).toLowerCase().replace(/[^a-z0-9]/g,'');}
function vals(o){var ks=Object.keys(o).filter(function(k){return k!=='row_number';});return ks.map(function(k){return s(o[k]);});}
var now=new Date();
var grid=$('GET meetings values').first().json.values||[];
var el=$('Read ERROR LOG').all().map(function(i){return i.json;});
var mailI=$('Read Mail correction').all().map(function(i){return i.json;});
var thI=$('Read Thesis correction').all().map(function(i){return i.json;});
var inv=$('Read INVESTORS').all().map(function(i){return i.json;});
var st=$('Read STARTUPS').all().map(function(i){return i.json;});
var trk=$('Read Deal Tracker').all().map(function(i){return i.json;});
var pipe=$input.all().map(function(i){return i.json;});

var tcols=Object.keys(trk[0]||{});var cInv=null;var cDeals=[];
for(var a=0;a<tcols.length;a++){var l=tcols[a].toLowerCase();if(!cInv&&(l.indexOf('investor')>=0||l.indexOf('vc name')>=0))cInv=tcols[a];if(l.indexOf('deals shared')>=0||l.indexOf('latest deal')>=0||l.indexOf('picked')>=0)cDeals.push(tcols[a]);}
var dInv={};for(var b=0;b<trk.length;b++){var kk=nz(trk[b][cInv]);if(kk)dInv[kk]=1;}

var unresolved={};
for(var c=0;c<el.length;c++){if(s(el[c].resolved)===''){var w=s(el[c].workflow)||'(blank)';unresolved[w]=(unresolved[w]||0)+1;}}
var tw=el.filter(function(r){return s(r.workflow)==='THESIS-WATCH';});
var open=tw.filter(function(r){return s(r.resolved)==='';}).map(function(r){return {row_number:r.row_number,timestamp:s(r.timestamp),investor:s(r.investor),error_type:s(r.error_type),details:s(r.details).slice(0,500)};});

function findInv(name){var k=nz(name);if(!k)return [];var ft=nz(s(name).split(/\s+/)[0]);return inv.filter(function(r){var n=nz(r.investor);if(!n)return false;return n===k||(k.length>=5&&n.indexOf(k)>=0)||(n.length>=5&&k.indexOf(n)>=0)||(ft.length>=5&&n.indexOf(ft)===0);});}

var thRaw=thI.map(vals);var P=null;
for(var d=0;d<thRaw.length;d++){var idx=-1;for(var e=0;e<thRaw[d].length;e++){if(thRaw[d][e].toLowerCase()==='sector'){idx=e;break;}}if(idx>0){P={firm:0,contact:1,email:2,sector:idx,stage:idx+1,cheque:idx+2,geo:idx+3,arr:idx+4};break;}}
var thesis=[];
if(P){for(var f=0;f<thRaw.length;f++){var rr=thRaw[f];var firm=rr[P.firm];if(!firm||firm.toLowerCase()==='firm name')continue;thesis.push({row:thI[f].row_number,firm:firm,contact:rr[P.contact]||'',email:rr[P.email]||'',sector:rr[P.sector]||'',stage:rr[P.stage]||'',cheque:rr[P.cheque]||'',geo:rr[P.geo]||'',arr:rr[P.arr]||''});}}

var mailHeaders=Object.keys(mailI[0]||{});
var mailRows=[];
for(var g=0;g<mailI.length;g++){var mv=vals(mailI[g]);var firmM='';for(var h=0;h<mv.length;h++){if(mv[h]){firmM=mv[h];break;}}if(!firmM||firmM.toLowerCase().indexOf('firm')===0)continue;var em='';for(var i2=0;i2<mv.length;i2++){if(mv[i2].indexOf('@')>=0){em=mv[i2];break;}}mailRows.push({row:mailI[g].row_number,firm:firmM,vals:mv,corrected_email:em});}

var mailCheck=[];
for(var j=0;j<mailRows.length;j++){var mr=mailRows[j];var hits=findInv(mr.firm);var ce=mr.corrected_email.toLowerCase();
 var invRows=hits.map(function(r){return {investor:s(r.investor),email:s(r.email),contact:s(r.contact_name||r.contact||''),match:s(r.email).toLowerCase()===ce};});
 var names={};for(var k2=0;k2<hits.length;k2++)names[s(hits[k2].investor)]=1;
 var q=0,sentWrong=0,sentOk=0,qWrong=0;var wrongSentRows=[];var wrongQueuedRows=[];
 for(var m=0;m<pipe.length;m++){var p=pipe[m];if(!names[s(p.investor)])continue;var pe=s(p.email).toLowerCase();var isSent=s(p.deal_shared).toLowerCase()==='yes';var isP=s(p.pause).toLowerCase()==='yes';
  if(isSent){if(ce&&pe&&pe!==ce){sentWrong++;if(wrongSentRows.length<40)wrongSentRows.push({row:p.row_number,deal_id:s(p.deal_id),startup:s(p.startup),investor:s(p.investor),email:pe,pause:s(p.pause),next_action:s(p.next_action)});}else sentOk++;}
  else if(!isP){q++;if(ce&&pe!==ce){qWrong++;if(wrongQueuedRows.length<40)wrongQueuedRows.push({row:p.row_number,deal_id:s(p.deal_id),startup:s(p.startup),investor:s(p.investor),email:pe,next_due:s(p.next_due)});}}}
 mailCheck.push({firm:mr.firm,corrected_email:mr.corrected_email,investors_rows:invRows,investors_hits:hits.length,queued_live:q,queued_wrong_email:qWrong,sent_wrong_email:sentWrong,sent_right_email:sentOk,wrong_queued:wrongQueuedRows,wrong_sent:wrongSentRows});}

var invByName={};for(var n2=0;n2<inv.length;n2++){var kx=nz(inv[n2].investor);if(kx&&!invByName[kx])invByName[kx]=inv[n2];}
function inbox(name){var r=invByName[nz(name)];if(r&&s(r.email))return s(r.email).toLowerCase();var hh=findInv(name);for(var z=0;z<hh.length;z++){if(s(hh[z].email))return s(hh[z].email).toLowerCase();}return 'NOEMAIL:'+nz(name);}
var gEmail={},gName={};
for(var o2=0;o2<pipe.length;o2++){var pp=pipe[o2];var sent2=s(pp.deal_shared).toLowerCase()==='yes';var pa=s(pp.pause).toLowerCase()==='yes';if(!sent2&&pa)continue;if(!s(pp.startup))continue;
 var ke=nz(pp.startup)+'|'+inbox(pp.investor);var kn=nz(pp.startup)+'|'+nz(pp.investor);
 var rec={row:pp.row_number,deal_id:s(pp.deal_id),startup:s(pp.startup),investor:s(pp.investor),sent:sent2?'Y':'N',email:s(pp.email),next_due:s(pp.next_due),notes:s(pp.notes).slice(0,60)};
 (gEmail[ke]=gEmail[ke]||[]).push(rec);(gName[kn]=gName[kn]||[]).push(rec);}
var dupE=[],dupN=[];
for(var q2 in gEmail){if(gEmail[q2].length>1)dupE.push({key:q2,rows:gEmail[q2]});}
for(var r2 in gName){if(gName[r2].length>1)dupN.push({key:r2,rows:gName[r2]});}

var start=-1,blockDate='';
for(var t2=0;t2<grid.length;t2++){var c0=s((grid[t2]||[])[0]);if(/^(\d{1,2}\/\d{1,2}\/\d{4}|\d{4}-\d{2}-\d{2})$/.test(c0)){var ok=false;for(var u2=t2+1;u2<Math.min(t2+8,grid.length);u2++){var rw=grid[u2]||[];if(/^\d+\s*meetings?/i.test(s(rw[1]))||/^\d+\s*meetings?/i.test(s(rw[0]))){ok=true;break;}}if(ok){start=t2;blockDate=c0;}}}
var stair={},stairRaw={};
if(start>=0){for(var v2=start+1;v2<grid.length;v2++){var row=grid[v2]||[];var mm=s(row[1]).match(/^(\d+)\s*meetings?/i);var off=2;if(!mm){mm=s(row[0]).match(/^(\d+)\s*meetings?/i);off=1;}
 if(!mm){if(Object.keys(stair).length)break;else continue;}
 var nM=parseInt(mm[1],10);
 for(var w2=off;w2<row.length;w2++){var nm=s(row[w2]);if(!nm)continue;var kz=nz(nm);if(stair[kz]===undefined||nM>stair[kz]){stair[kz]=nM;stairRaw[kz]=nm;}}}}

var scols=Object.keys(st[0]||{});
var startups=[];
for(var x2=0;x2<st.length;x2++){var sr=st[x2];if(s(sr.active).toLowerCase()!=='yes')continue;var nmS=s(sr.startup);if(!nmS)continue;
 var kS=nz(nmS);var mt=null;for(var y2 in stair){var kk2=(y2==='caffeinacoffee')?'caffenacoffee':y2;if(kk2===kS||(kk2.length>=4&&kS.length>=4&&(kk2.indexOf(kS)===0||kS.indexOf(kk2)===0))){if(mt===null||stair[y2]>mt)mt=stair[y2];}}
 startups.push({startup:nmS,owner:s(sr.owner),sector:s(sr.sector).slice(0,180),stage:s(sr.stage).slice(0,80),raise:s(sr.raise_inr_cr),revenue:s(sr.revenue||sr.arr||'').slice(0,80),meetings:mt===null?'NOT_IN_STAIRCASE':mt});}

var maxN=0;for(var z2=0;z2<pipe.length;z2++){var idd=s(pipe[z2].deal_id);if(idd.charAt(0)==='D'){var vv=parseInt(idd.slice(1),10);if(!isNaN(vv)&&vv>maxN)maxN=vv;}}
var load={};var perStartup={};
for(var a3=0;a3<pipe.length;a3++){var p3=pipe[a3];if(s(p3.deal_shared).toLowerCase()==='yes')continue;if(s(p3.pause).toLowerCase()==='yes')continue;var dd=s(p3.next_due);if(dd)load[dd]=(load[dd]||0)+1;var ks3=s(p3.startup);if(ks3)perStartup[ks3]=(perStartup[ks3]||0)+1;}

return [{json:{
 now_utc:now.toISOString(),now_ist:new Date(now.getTime()+19800000).toISOString(),
 guards:{pipeline_rows:pipe.length,tracker_rows:trk.length,tracker_distinct_investors:Object.keys(dInv).length,investors_rows:inv.length,startups_rows:st.length,error_log_rows:el.length},
 tracker_inv_col:cInv,tracker_deal_cols:cDeals,
 pipeline_columns:Object.keys(pipe[0]||{}),investor_columns:Object.keys(inv[0]||{}),startup_columns:scols,
 max_deal_num:maxN,
 unresolved_by_workflow:unresolved,
 thesis_watch_total:tw.length,open_thesis_watch:open,
 thesis_header_found:!!P,thesis_rows:thesis,
 mail_headers:mailHeaders,mail_rows_count:mailRows.length,mail_check:mailCheck,
 dup_by_inbox_count:dupE.length,dup_by_inbox:dupE.slice(0,60),
 dup_by_name_count:dupN.length,
 meetings_block_date:blockDate,meetings_names:Object.keys(stair).length,
 active_startups:startups,
 load_by_date:load,per_startup_unsent:perStartup
}}];
